    bool isTrackVisible(String path) {
      // Search mode swaps the entire list; keep the visibility contract simple
      // for the folder browser rows.
      if (searchTerm.value.isNotEmpty) return false;
      if (!scroll.hasClients) return false;

      final tracks = ctrl.tracks;
      final index = tracks.indexWhere((t) => t.path == path);
      if (index < 0) return false;

      // With reverse: true, offset 0 is the visual bottom, so child index is
      // hasUp + (tracks.length - 1 - index) (same mapping as scrollToTrack).
      final hasUp = ctrl.currentPath != null ? 1 : 0;
      final childIndex = hasUp + (tracks.length - 1 - index);
      final pos = scroll.position;

      // ignore: use_build_context_synchronously
      final rowHeight = Theme.of(context).extension<AppGeometry>()!.rowHeight;
      final rowTop = childIndex * rowHeight;
      final rowBottom = rowTop + rowHeight;

      final viewportTop = pos.pixels;
      final viewportBottom = viewportTop + pos.viewportDimension;

      return rowBottom > viewportTop && rowTop < viewportBottom;
    }

